// Reads .env and writes js/sync/firebase-config.js.
// The site has no build step, so the generated file is committed and served
// as-is. Firebase web config is public by design; firestore.rules is what
// protects the data.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';

const FIELDS = {
  apiKey: 'FIREBASE_API_KEY',
  authDomain: 'FIREBASE_AUTH_DOMAIN',
  projectId: 'FIREBASE_PROJECT_ID',
  storageBucket: 'FIREBASE_STORAGE_BUCKET',
  messagingSenderId: 'FIREBASE_MESSAGING_SENDER_ID',
  appId: 'FIREBASE_APP_ID'
};
const REQUIRED = ['apiKey', 'authDomain', 'projectId', 'appId'];

if (!existsSync('.env')) {
  console.error('Không tìm thấy .env. Sao chép .env.example thành .env rồi điền cấu hình Firebase.');
  process.exit(1);
}

const env = Object.fromEntries(
  readFileSync('.env', 'utf8').split('\n')
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('#') && line.includes('='))
    .map(line => {
      const i = line.indexOf('=');
      return [line.slice(0, i).trim(), line.slice(i + 1).trim().replace(/^['"]|['"]$/g, '')];
    })
);

const config = {};
for (const [field, name] of Object.entries(FIELDS)) if (env[name]) config[field] = env[name];

const missing = REQUIRED.filter(f => !config[f]).map(f => FIELDS[f]);
if (missing.length) {
  console.error(`Thiếu biến trong .env: ${missing.join(', ')}`);
  process.exit(1);
}

writeFileSync('js/sync/firebase-config.js', `// GENERATED by scripts/gen-firebase-config.mjs from .env. Do not edit by hand;
// change .env and run \`npm run config\`.
// Firebase web config is not secret; access is enforced by firestore.rules.
export const FIREBASE_CONFIG = ${JSON.stringify(config, null, 2)};
`);
console.log(`Đã ghi js/sync/firebase-config.js (project: ${config.projectId})`);
